contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 probe) public payable {
        require(probe < type(uint256).max);
        uint256 before = c.tokenBalance(address(this));
        c.airDrop();
        uint256 afterB = c.tokenBalance(address(this));
        assert(before == 0 && afterB == before + 20);
    }
    fallback(bytes calldata) external payable returns (bytes memory) {
        return abi.encodePacked(keccak256(abi.encodePacked("Nu Token")));
    }
    receive() external payable {}
}

