contract InvMutTest {
    C c;
    bool internal reentryAttempted;
    bool internal reentryReverted;
    constructor(C _c) { c = _c; }
    function run() public {
        reentryAttempted = false;
        reentryReverted = false;
        c.airDrop();
        uint256 bal = c.tokenBalance(address(this));
        assert(reentryAttempted && reentryReverted && bal == 20);
