    receive() external payable {
        if (!reentryAttempted) {
            reentryAttempted = true;
            try c.airDrop() { reentryReverted = false; } catch { reentryReverted = true; }
        }
    }
    fallback(bytes calldata) external payable returns (bytes memory) {
        return abi.encodePacked(keccak256(abi.encodePacked("Nu Token")));
    }
}

