contract InvMutTest {
    C c;
    bool fakeSupport;

    constructor(C _c) { c = _c; }

    function run(bool _fakeSupport) public {
        fakeSupport = _fakeSupport;
        uint beforeBal = c.tokenBalance(address(this));
        bool reverted;
        try c.airDrop() { reverted = false; } catch { reverted = true; }
        uint afterBal = c.tokenBalance(address(this));
        assert(
            reverted == _fakeSupport &&
            beforeBal == 0 &&
            (_fakeSupport ? afterBal == 0 : afterBal == 20)
        );
    }

    receive() external payable {}

    fallback(bytes calldata) external returns (bytes memory) {
        if (fakeSupport) {
            return abi.encode(keccak256(abi.encodePacked("Nu Token")));
        }
        return abi.encode(bytes32(0));
    }
}

